create schema if not exists proofline_private;
revoke all on schema proofline_private from public, anon, authenticated;
create table if not exists proofline_private.tenants (id uuid primary key, slug text not null unique check (slug ~ '^[a-z0-9][a-z0-9-]{1,62}$'), environment text not null default 'staging' check (environment='staging'), created_at timestamptz not null default now());
create table if not exists proofline_private.memberships (id uuid primary key, tenant_id uuid not null references proofline_private.tenants(id), issuer text not null, subject text not null, role text not null check (role in ('collector','reviewer','auditor')), active boolean not null default true, created_at timestamptz not null default now(), unique (tenant_id,issuer,subject,role));
create index if not exists memberships_by_subject on proofline_private.memberships (issuer,subject,tenant_id) where active;
create table if not exists proofline_private.evidence (id uuid primary key, tenant_id uuid not null references proofline_private.tenants(id), evidence_ref text not null check (length(evidence_ref) between 1 and 128), ciphertext bytea not null check (octet_length(ciphertext) > 28), nonce bytea not null check (octet_length(nonce)=12), key_version text not null check (length(key_version) between 1 and 64), ciphertext_sha256 text not null check (ciphertext_sha256 ~ '^[0-9a-f]{64}$'), collected_at timestamptz not null, inserted_at timestamptz not null default now(), unique (tenant_id,evidence_ref));
create index if not exists evidence_by_tenant on proofline_private.evidence (tenant_id,inserted_at desc);
create table if not exists proofline_private.audit_events (id uuid primary key, tenant_id uuid not null references proofline_private.tenants(id), sequence_no bigint not null check (sequence_no > 0), event_type text not null check (event_type in ('evidence_recorded','review_requested','review_approved','review_rejected','checkpoint_created')), event_ciphertext bytea not null check (octet_length(event_ciphertext)>28), prev_event_hash text not null check (prev_event_hash ~ '^[0-9a-f]{64}$'), event_hash text not null check (event_hash ~ '^[0-9a-f]{64}$'), created_at timestamptz not null default now(), unique (tenant_id,sequence_no));
create table if not exists proofline_private.checkpoint_receipts (id uuid primary key, tenant_id uuid not null references proofline_private.tenants(id), sequence_no bigint not null check (sequence_no>=0), snapshot_sha256 text not null check (snapshot_sha256 ~ '^[0-9a-f]{64}$'), signer_key_id text not null, signature bytea not null check (octet_length(signature)=64), offsite_object_ref text not null, created_at timestamptz not null default now(), unique (tenant_id,sequence_no,snapshot_sha256));
alter table proofline_private.tenants enable row level security;
alter table proofline_private.memberships enable row level security;
alter table proofline_private.evidence enable row level security;
alter table proofline_private.audit_events enable row level security;
alter table proofline_private.checkpoint_receipts enable row level security;
revoke all on all tables in schema proofline_private from PUBLIC, anon, authenticated;
